#!/usr/bin/env bash
# MOVED: nucleus/spawn-all.sh -> scripts/spawn-all.sh (goal 10224 S4). A compat stub, kept for one release: it runs the moved script with the same
# arguments (or sources it, when it is sourced). Each use stamps var/reorg_stubs/ for the census. Generated by
# devtools/reorg/apply.py from devtools/reorg/map.tsv.
_astryx_stub_root=$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]:-$0}")")/.." && pwd)
{ mkdir -p "$_astryx_stub_root/var/reorg_stubs" && printf '%s\t%s\n' "$PPID" "$(tr '\0' ' ' < /proc/$PPID/cmdline)" \
    > "$_astryx_stub_root/var/reorg_stubs/nucleus__spawn-all.sh"; } 2>/dev/null || true
if [ "${BASH_SOURCE[0]:-$0}" != "$0" ]; then . "$_astryx_stub_root/scripts/spawn-all.sh" "$@"; return $?; fi
exec "$_astryx_stub_root/scripts/spawn-all.sh" "$@"
